"""Builds FICTIONAL Salesforce-style export fixtures (no real customer data).
Mimics the common Salesforce export shapes: Classic 'Excel .xls' (HTML table + footer),
Excel 2003 XML (.xls), Lightning 'Formatted' .xlsx (title block, grouped rows, subtotals, footer),
genuine Excel 97-2003 BIFF .xls (summary report with '(n records)' group rows), and CSV with footer."""
import os, random, subprocess, shutil, datetime
from openpyxl import Workbook
from openpyxl.styles import Font
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fixtures'); os.makedirs(D, exist_ok=True)
random.seed(11)
P = 'Sample: Northwind Freight'
A = [  # name, id, parent name, parent id, owner, type, city, state, phone, impl stage
 (P, '001SMPL00000201AAA', '', '', 'Sample Rep (Casey Fox)', 'Customer - Direct', 'Flint', 'MI', '(555) 010-0201', 'Implementation Call'),
 (P + ' – Flint Yard', '001SMPL00000202AAA', P, '001SMPL00000201AAA', 'Sample Rep (Casey Fox)', 'Customer - Location', 'Flint', 'MI', '(555) 010-0202', 'Monitor & Control'),
 (P + ' – Saginaw Depot', '001SMPL00000203AAA', P, '001SMPL00000201AAA', 'Sample Rep (Casey Fox)', 'Customer - Location', 'Saginaw', 'MI', '(555) 010-0203', 'Implementation Call'),
 (P + ' – Lansing Shop', '001SMPL00000204AAA', P, '001SMPL00000201AAA', 'Sample Rep (Dee Park)', 'Customer - Location', 'Lansing', 'MI', '(555) 010-0204', 'Pending Docs'),
 (P + ' – Lansing Reefer', '001SMPL00000205AAA', P + ' – Lansing Shop', '001SMPL00000204AAA', 'Sample Rep (Dee Park)', 'Customer - Location', 'Lansing', 'MI', '', 'Application Follow-up'),
 (P, '001SMPL00000206AAA', P, '001SMPL00000201AAA', 'Sample Rep (Casey Fox)', 'Customer - Location', 'Bay City', 'MI', '', 'Application Follow-up'),
 ('Sample: Birch Lane Plumbing', '001SMPL00000211AAA', '', '', 'Sample Rep (Dee Park)', 'Customer - Direct', 'Toledo', 'OH', '(555) 010-0211', 'Monitor & Control'),
 ('Sample: Birch Lane Plumbing – East', '001SMPL00000212AAA', 'Sample: Birch Lane Plumbing', '001SMPL00000211AAA', 'Sample Rep (Dee Park)', 'Customer - Location', 'Toledo', 'OH', '', 'Implementation Call'),
]
# 1) Classic "Export Details → Excel .xls" = HTML table with footer rows
H = ['Account Name', 'Account ID', 'Parent Account', 'Parent Account ID', 'Account Owner', 'Type', 'Billing City', 'Billing State/Province', 'Phone', 'Implementation Stage', 'Created Date']
esc = lambda s: s.replace('&', '&amp;').replace('<', '&lt;')
rows = ''.join('<tr>' + ''.join(f'<td>{esc(c) if c else "&nbsp;"}</td>' for c in (*r, f'{random.randint(1,12)}/{random.randint(1,28)}/2026')) + '</tr>\n' for r in A)
foot = ''.join(f'<tr><td colspan="{len(H)}">{t}</td></tr>\n' for t in ['&nbsp;', 'Copyright (c) 2000-2026 salesforce.com, inc. All rights reserved.', 'Confidential Information - Do Not Distribute', 'Generated By:  Sample User  11/23/2026 1:02 PM', 'Sample Company Inc.'])
open(f'{D}/sf_classic_accounts.xls', 'w', encoding='utf-8').write('<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"></head><body><table border="1">\n<tr>' + ''.join(f'<th>{h}</th>' for h in H) + '</tr>\n' + rows + foot + '</table></body></html>')
# 2) Excel 2003 XML (SpreadsheetML) named .xls — contacts
C = [('Sample:', 'Ana Ruiz', 'Fleet Director', 'ana.ruiz@example.com', '(555) 010-0301', P, '001SMPL00000201AAA', 'Flint', 'Decision Maker'),
     ('Sample:', 'Raj Mehta', 'Controller', 'raj.mehta@example.com', '(555) 010-0302', P, '001SMPL00000201AAA', 'Flint', 'Billing / AP'),
     ('Sample:', 'Ben Ode', 'Yard Lead', 'ben.ode@example.com', '(555) 010-0303', P + ' – Flint Yard', '001SMPL00000202AAA', 'Flint', 'Card Admin'),
     ('Sample:', 'Lia Chen', 'Depot Manager', 'lia.chen@example.com', '(555) 010-0304', P + ' – Saginaw Depot', '001SMPL00000203AAA', 'Saginaw', 'Billing Contact'),
     ('Sample:', 'Tom Reyes', 'Owner', 'tom.reyes@example.com', '(555) 010-0305', 'Sample: Birch Lane Plumbing', '001SMPL00000211AAA', 'Toledo', 'Decision Maker')]
CH = ['First Name', 'Last Name', 'Title', 'Email', 'Phone', 'Account Name', 'Account ID', 'Mailing City', 'Contact Role', 'Created Date']
cell = lambda v, t='String': f'<Cell><Data ss:Type="{t}">{esc(v)}</Data></Cell>'
xrows = '<Row>' + ''.join(cell(h) for h in CH) + '</Row>\n' + ''.join('<Row>' + ''.join(cell(v) for v in c) + cell(f'2026-0{random.randint(1,9)}-1{random.randint(0,9)}T00:00:00.000', 'DateTime') + '</Row>\n' for c in C)
open(f'{D}/sf_contacts_xml2003.xls', 'w', encoding='utf-8').write('<?xml version="1.0" encoding="UTF-8"?>\n<?mso-application progid="Excel.Sheet"?>\n<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet" xmlns:x="urn:schemas-microsoft-com:office:excel">\n<Styles><Style ss:ID="s1"><NumberFormat ss:Format="Short Date"/></Style></Styles>\n<Worksheet ss:Name="Contacts"><Table>\n' + xrows + '</Table></Worksheet></Workbook>')
# 3) Lightning "Formatted" .xlsx — opportunities grouped by account, subtotals, footer
wb = Workbook(); ws = wb.active; ws.title = 'Sample Opportunities'
ws.append(['Sample Opportunities by Account']); ws['A1'].font = Font(bold=True, size=14)
ws.append(['Filtered By:']); ws.append(['    Close Date: Current FY']); ws.append(['As of 11/23/2026 1:05 PM']); ws.append([])
ws.append(['Account Name', 'Opportunity Name', 'Opportunity ID', 'Stage', 'Close Date', 'Amount', 'Opportunity Owner'])
O = [(A[0], 'Sample: Northwind fleet card rollout', '006SMPL00000201AAA', 'Closed Won', 30000), (A[0], 'Sample: Northwind telematics add-on', '006SMPL00000202AAA', 'Proposal/Price Quote', 8000),
     (A[2], 'Sample: Saginaw depot cards', '006SMPL00000203AAA', 'Closed Won', 12000), (A[6], 'Sample: Birch Lane fuel program', '006SMPL00000211AAA', 'Negotiation/Review', 15000)]
tot = 0
from itertools import groupby
for acct, grp in groupby(O, key=lambda o: o[0][0] + o[0][1]):
    grp = list(grp); sub = 0
    for k, o in enumerate(grp):
        r = ws.max_row + 1
        ws.append([o[0][0] if k == 0 else None, o[1], o[2], o[3], datetime.date(2026, random.randint(1, 12), random.randint(1, 28)), o[4], o[0][4]])
        ws.cell(r, 5).number_format = 'm/d/yyyy'; ws.cell(r, 6).number_format = '"$"#,##0.00'; sub += o[4]
    ws.append(['Subtotal', None, None, None, None, sub, None]); tot += sub
ws.append(['Total', None, None, None, None, tot, None]); ws.append([])
ws.append(['Confidential Information - Do Not Distribute']); ws.append(['Copyright (c) 2000-2026 salesforce.com, inc. All rights reserved.'])
ws.merge_cells('A1:G1'); wb.save(f'{D}/sf_opportunities_formatted.xlsx')
# 4) Genuine Excel 97-2003 (.xls BIFF8) — summary report of 300 cases grouped by account (big enough to split the string table)
wb = Workbook(); ws = wb.active; ws.title = 'Sample Cases'
ws.append(['Sample Open Cases by Account']); ws.append([])
ws.append(['Case Number', 'Subject', 'Status', 'Priority', 'Date/Time Opened', 'Contact Name', 'Account Name'])
n = 0
for a in A[:4] + A[6:8]:
    k = 50
    ws.append([f'Account Name: {a[0]} ({k} records)'])
    for i in range(k):
        n += 1; r = ws.max_row + 1
        ws.append([f'{12000 + n:08d}', f'Sample subject {n}: card replacement request number {n * 7919 % 100000}', random.choice(['New', 'Working', 'Escalated']), random.choice(['Low', 'Medium', 'High']),
                   datetime.datetime(2026, random.randint(1, 11), random.randint(1, 28), random.randint(7, 18), random.choice([0, 15, 30, 45])), '', None])
        ws.cell(r, 5).number_format = 'm/d/yyyy h:mm AM/PM'
ws.append([f'Grand Totals ({n} records)']); ws.append([]); ws.append(['Confidential Information - Do Not Distribute'])
tmp = f'{D}/_cases_tmp.xlsx'; wb.save(tmp)
subprocess.run(['soffice', '--headless', '--convert-to', 'xls:MS Excel 97', '--outdir', D, tmp], check=True, capture_output=True)
shutil.move(f'{D}/_cases_tmp.xls', f'{D}/sf_cases_excel97.xls'); os.remove(tmp)
# 5) CSV (Details only) — billing / credit, with Salesforce footer
import csv
with open(f'{D}/sf_billing_credit.csv', 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f, quoting=csv.QUOTE_ALL)
    w.writerow(['Account Name', 'Account ID', 'Billing Level', 'Credit Line', 'Billing Frequency', 'Payment Terms', 'Billing Contact', 'Fleet Size', 'Program'])
    w.writerow([P, '001SMPL00000201AAA', 'Parent', '$150,000.00', 'Weekly', 'Net 14', 'Sample: Raj Mehta', '120', 'Sample Fleet Program A'])
    w.writerow([P + ' – Flint Yard', '001SMPL00000202AAA', 'Parent', '', '', '', '', '40', 'Sample Fleet Program A'])
    w.writerow([P + ' – Saginaw Depot', '001SMPL00000203AAA', 'Child', 'USD 25,000.00', 'Monthly', 'Net 15', 'Sample: Lia Chen', '35', 'Sample Fleet Program A'])
    w.writerow(['Sample: Birch Lane Plumbing', '001SMPL00000211AAA', 'Parent', '40000', 'Monthly', 'Net 30', 'Sample: Tom Reyes', '12', 'Sample Fleet Program B'])
    w.writerow([]); w.writerow(['"Sample Billing Report"']); w.writerow(['Copyright (c) 2000-2026 salesforce.com, inc. All rights reserved.']); w.writerow(['Confidential Information - Do Not Distribute']); w.writerow(['Generated By:  Sample User  11/23/2026 1:06 PM'])
print('fixtures:', sorted(os.listdir(D)))
